// Шаги пройдены в живом браузере (реальная дата в нём тоже 3.10.2026); page.clock.setFixedTime — по плану, в живом режиме недоступен.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { setFixedTimeKeepingSession } from '../_helpers/clock';
import { addDays, daysInMonth, dotDate, gregMonthName, isoDate, nextHebrewDay } from '../_helpers/dates';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

async function deleteQaDates(page: Page) {
  await page.goto('/home');
  await expect(page.getByRole('button', { name: 'הוספת תאריך חשוב' })).toBeVisible({ timeout: 20_000 });
  await page.waitForLoadState('networkidle').catch(() => {});
  const edit = page.getByRole('button', { name: /QA-AUTO-.*: פתיחה לעריכה$/ });
  for (let guard = 0; guard < 10; guard++) {
    const before = await edit.count();
    if (before === 0) break;
    await edit.first().click();
    await page.getByRole('button', { name: 'מחיקת התאריך' }).click();
    await page.getByRole('button', { name: 'מחיקה', exact: true }).click();
    await expect(edit).toHaveCount(before - 1);
  }
}

// «Сегодня» для теста. Дата ввода 14.03.2025 (= י״ד אדר תשפ״ה) — прошлая, остаётся фиксированной по смыслу кейса.
// «האזכרה הבאה» зависит от сегодняшнего дня; кейс проверяет вариант с двумя אדר (следующий ט״ו אדר — в מעוברת).
// Если от реального сегодня ближайший ט״ו אדר приходится на אדר א׳ — работаем на реальном времени (часы не трогаем).
// Иначе (високосный год уже прошёл) — часы фиксируются на 3.10.2026 БЕЗ потери сессии (хелпер clock: свежий
// токен на реальном времени → setFixedTime → expires_at = fake + 1 ч), как описано в .qa/context.md.
const CASE_DAY = new Date('2026-10-03T09:00:00+03:00');
function nextAdar15(from: Date) {
  const first = nextHebrewDay(from, 15, (m) => m.startsWith('אדר'));
  if (!first || !/א׳$/.test(hebrewMonthOf(first))) return null;
  const second = nextHebrewDay(addDays(first, 1), 15, (m) => m === 'אדר ב׳');
  return second ? { first, second } : null;
}
function hebrewMonthOf(d: Date) {
  return new Intl.DateTimeFormat('he-u-ca-hebrew', { month: 'long' }).format(d);
}

test.describe('Важные даты и אזכרות', () => {
  test('ID-03 אזכרה — будущая дата недоступна, «אחרי השקיעה» сдвигает еврейский день, אדר א׳/ב׳ #6a86f7e6 @data @mobile', async ({ page }) => {
    // 1. «Сегодня» (реальное или 3.10.2026 — см. выше). `/home` → «+» → «אזכרה».
    let today = new Date();
    let adar = nextAdar15(today);
    if (!adar) {
      today = CASE_DAY;
      adar = nextAdar15(today)!;
      await setFixedTimeKeepingSession(page, CASE_DAY);
    }
    const Y = today.getFullYear();
    const M = today.getMonth();
    const D = today.getDate();
    const iso = (y: number, m0: number, d: number) => isoDate(new Date(y, m0, d, 12));
    try {
      await page.goto('/home');
      await page.getByRole('button', { name: 'הוספת תאריך חשוב' }).click();
      await page.getByRole('button', { name: 'אזכרה', exact: true }).click();
      const dialog = page.getByRole('dialog');
      await dialog.getByRole('textbox', { name: 'שם הנפטר' }).fill('QA-AUTO-נפטר');

      // Дни после сегодня недоступны (в кейсе 4–31 октября), «החודש הבא» неактивна
      for (let d = D + 1; d <= daysInMonth(Y, M); d++) {
        const radio = dialog.getByRole('radio', { name: new RegExp(`^${iso(Y, M, d)}, .*לא ניתן לבחור תאריך עתידי$`) });
        await expect(radio).toHaveAttribute('aria-disabled', 'true');
      }
      await expect(dialog.getByRole('radio', { name: new RegExp(`^${iso(Y, M, D)}, `) })).not.toHaveAttribute('aria-disabled', 'true');
      await expect(dialog.getByRole('button', { name: 'החודש הבא' })).toBeDisabled();

      // Выбор месяца/года: будущие месяцы (в кейсе נובמבר/דצמבר 2026) и «השנה הבאה» неактивны
      await dialog.getByRole('button', { name: `${gregMonthName(Y, M)} ${Y}: בחירת שנה וחודש` }).click();
      await expect(dialog.getByRole('button', { name: 'השנה הבאה' })).toBeDisabled();
      for (let m = M + 1; m <= 11; m++) {
        await expect(dialog.getByRole('button', { name: new RegExp(`^${gregMonthName(Y, m)} ${Y}, לא ניתן לבחור תאריך עתידי`) })).toBeDisabled();
      }

      // 2. Заголовок месяца → «השנה הקודמת» (до 2025) → «מרץ 2025» → день 14; прочитать пояснение.
      // (окно выбора месяца/года уже открыто)
      for (let y = Y; y > 2025; y--) {
        await dialog.getByRole('button', { name: 'השנה הקודמת' }).click();
      }
      await dialog.getByRole('button', { name: 'מרץ 2025' }).click();
      await dialog.getByRole('radio', { name: /^2025-03-14, / }).click();
      await expect(dialog.getByText(/יישמר: 14\.03\.2025 · י״ד אדר תשפ״ה/)).toBeVisible();
      await expect(dialog.getByText('האזכרה תסומן בכל שנה ב־י״ד אדר.')).toBeVisible();
      await expect(
        dialog.getByText('בשנה מעוברת, שיש בה שני חודשי אדר, האזכרה תסומן גם ב־י״ד אדר א׳ וגם ב־י״ד אדר ב׳.'),
      ).toBeVisible();

      // 3. Отметить «הפטירה הייתה אחרי השקיעה» → пояснение → «הוסף תאריך».
      await dialog.getByRole('checkbox', { name: 'הפטירה הייתה אחרי השקיעה' }).click();
      await expect(dialog.getByText(/יישמר: 14\.03\.2025 · ט״ו אדר תשפ״ה — הפטירה אחרי השקיעה/)).toBeVisible();
      await expect(dialog.getByText('האזכרה תסומן בכל שנה ב־ט״ו אדר.')).toBeVisible();
      await expect(
        dialog.getByText('בשנה מעוברת, שיש בה שני חודשי אדר, האזכרה תסומן גם ב־ט״ו אדר א׳ וגם ב־ט״ו אדר ב׳.'),
      ).toBeVisible();
      await dialog.getByRole('button', { name: 'הוסף תאריך' }).click();
      await expect(page.getByRole('dialog')).toHaveCount(0);

      // 4. Прочитать запись на `/home`; карандаш → проверить checkbox.
      const open = page.getByRole('button', { name: 'אזכרה, QA-AUTO-נפטר: פתיחת סדר האזכרה' });
      await expect(open).toBeVisible({ timeout: 20_000 });
      // На 3.10.2026 — «… ט״ו אדר א׳ – 22.02.2027 · ט״ו אדר ב׳ – 24.03.2027» (строка кейса).
      await expect(open).toContainText(`האזכרה הבאה: ט״ו אדר א׳ – ${dotDate(adar.first)} · ט״ו אדר ב׳ – ${dotDate(adar.second)}`);
      const row = open.locator('xpath=..'); // строка записи: блок даты + кнопки
      await expect(row).toContainText('אדר');
      await expect(row).toContainText('ט״ו');
      await page.getByRole('button', { name: 'אזכרה, QA-AUTO-נפטר: פתיחה לעריכה' }).click();
      await expect(page.getByRole('dialog').getByRole('checkbox', { name: 'הפטירה הייתה אחרי השקיעה' })).toHaveAttribute('aria-checked', 'true');
      await page.getByRole('dialog').getByRole('button', { name: 'סגירה' }).click();
    } finally {
      // 5. Уборка: «מחיקת התאריך» → «מחיקה».
      await deleteQaDates(page);
      await page.reload();
      await expect(page.getByRole('button', { name: 'הוספת תאריך חשוב' })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('QA-AUTO-')).toHaveCount(0);
    }
  });
});
